(3658642, 510919, 63812, '<td valign="top">basic editing, how?</td>', 'basic editing, how?', '2007-05-17 00:51:06.000000', NULL, 1),
(3658659, 512718, 46806, '<td valign="top">I like this perspective.  The duct in the upper midright is  a bit distracting, and i would like it better if the last teir on the left wasnn''t cropped out.</td>', 'I like this perspective.  The duct in the upper midright is  a bit distracting, and i would like it better if the last teir on the left wasnn''t cropped out.', '2007-05-17 00:56:10.000000', NULL, 1),
(3658711, 512497, 30454, '<td valign="top">Too small. Check the resizing tutorial</td>', 'Too small. Check the resizing tutorial', '2007-05-17 01:13:58.000000', NULL, 1),
(3658742, 512129, 76430, '<td valign="top">Lovely scene and composition gets one of my higher scores, but questionable about meeting the challenge.</td>', 'Lovely scene and composition gets one of my higher scores, but questionable about meeting the challenge.', '2007-05-17 01:23:22.000000', NULL, 1),
(3658746, 511757, 30454, '<td valign="top">Nice tones. One of my top 5.</td>', 'Nice tones. One of my top 5.', '2007-05-17 01:24:15.000000', NULL, 1),
(3658750, 511049, 30454, '<td valign="top">Road and lights give very good feeling of vanishing point. My pick for one of the ribbon.</td>', 'Road and lights give very good feeling of vanishing point. My pick for one of the ribbon.', '2007-05-17 01:25:03.000000', NULL, 1),
(3658754, 511080, 30454, '<td valign="top">pick for a top 10. The scratch/moving object is bit distracting. Darn basic editing, right?</td>', 'pick for a top 10. The scratch/moving object is bit distracting. Darn basic editing, right?', '2007-05-17 01:26:25.000000', NULL, 1),
(3658764, 510197, 76430, '<td valign="top">I didn''t like the graininess to begin with, but it''s growing on me.  It definitely meets the challenge, and the guy walking towards the vanishing point adds to it.</td>', 'I didn''t like the graininess to begin with, but it''s growing on me.  It definitely meets the challenge, and the guy walking towards the vanishing point adds to it.', '2007-05-17 01:29:47.000000', NULL, 1),
(3658767, 511069, 76430, '<td valign="top">Nice arrangement of a close vanishing point.</td>', 'Nice arrangement of a close vanishing point.', '2007-05-17 01:30:59.000000', NULL, 1),
(3658821, 512664, 76430, '<td valign="top">Beautiful misty shot</td>', 'Beautiful misty shot', '2007-05-17 01:51:52.000000', NULL, 1),
(3658823, 512360, 76430, '<td valign="top">I think it would have worked out better if it was level for this picture.</td>', 'I think it would have worked out better if it was level for this picture.', '2007-05-17 01:53:51.000000', NULL, 1),
(3658828, 512901, 76430, '<td valign="top">My attention is torn between the title object and the challenge object.</td>', 'My attention is torn between the title object and the challenge object.', '2007-05-17 01:56:01.000000', NULL, 1),
(3658835, 510227, 76430, '<td valign="top">Great angle and picture, but the rails seem to converge behind you as well as the last tiny bit at the horizon.</td>', 'Great angle and picture, but the rails seem to converge behind you as well as the last tiny bit at the horizon.', '2007-05-17 02:00:10.000000', NULL, 1),
(3658839, 510895, 76430, '<td valign="top">I''d like to see this with a lower, shallower angle.</td>', 'I''d like to see this with a lower, shallower angle.', '2007-05-17 02:02:00.000000', NULL, 1),
(3658863, 510898, 76430, '<td valign="top">Excellent light reflection on the rails.</td>', 'Excellent light reflection on the rails.', '2007-05-17 02:18:27.000000', NULL, 1),
(3658887, 512522, 61336, '<td valign="top">I like the low point of view and dof</td>', 'I like the low point of view and dof', '2007-05-17 02:39:21.000000', NULL, 1),
(3658902, 511920, 61336, '<td valign="top">I like the colors and repetition but the gray border is not so flattering. <br/>A little underexposed IMHO.</td>', 'I like the colors and repetition but the gray border is not so flattering. A little underexposed IMHO.', '2007-05-17 02:46:10.000000', NULL, 1),
(3658918, 512296, 25787, '<td valign="top">Something interesting in the foreground would really improve this.</td>', 'Something interesting in the foreground would really improve this.', '2007-05-17 02:53:59.000000', NULL, 1),
(3658921, 512411, 61336, '<td valign="top">Different than all the others I''ve seen so far. Focus is a little soft i think.</td>', 'Different than all the others I''ve seen so far. Focus is a little soft i think.', '2007-05-17 02:54:44.000000', NULL, 1),
(3658923, 511757, 61336, '<td valign="top">I think B/W works fine in this one. Nice dramatic sky.</td>', 'I think B/W works fine in this one. Nice dramatic sky.', '2007-05-17 02:55:51.000000', NULL, 1),
