(3662402, 512503, 46336, '<td valign="top">This shot deserves a better title. Excellent lighting and shadows. Only negative is that my eyes can''t decide if the focal point is the vanishing point or the guy. Regardless, this is a superb shot.</td>', 'This shot deserves a better title. Excellent lighting and shadows. Only negative is that my eyes can''t decide if the focal point is the vanishing point or the guy. Regardless, this is a superb shot.', '2007-05-18 04:22:43.000000', NULL, 1),
(3662403, 512705, 35602, '<td valign="top">I think that this is vanishing only due to the crop. Image is kind of uninteresting.</td>', 'I think that this is vanishing only due to the crop. Image is kind of uninteresting.', '2007-05-18 04:26:39.000000', NULL, 1),
(3662404, 512878, 35602, '<td valign="top">Don''t get it.</td>', 'Don''t get it.', '2007-05-18 04:26:57.000000', NULL, 1),
