(3662407, 510702, 35602, '<td valign="top">Nice crop.  This one suffers, unfortunately, from the sky.  That would have made the image sing,though we have no control over that.</td>', 'Nice crop.  This one suffers, unfortunately, from the sky.  That would have made the image sing,though we have no control over that.', '2007-05-18 04:28:53.000000', NULL, 1),
(3662409, 511752, 35602, '<td valign="top">Hmmm.  Like the linear style, but I don''t get vanish from it.  Needs less exposure as well.</td>', 'Hmmm.  Like the linear style, but I don''t get vanish from it.  Needs less exposure as well.', '2007-05-18 04:30:18.000000', NULL, 1),
(3662412, 512348, 35602, '<td valign="top">Needs something more.  I think that as a comp it is very nice, but perhaps a lower perspective, or closer, might have given a better idea of vanish.</td>', 'Needs something more.  I think that as a comp it is very nice, but perhaps a lower perspective, or closer, might have given a better idea of vanish.', '2007-05-18 04:31:53.000000', NULL, 1),
